```typescript
import type { LinksFunction, LoaderFunctionArgs } from "react-router";
import { redirect, useLoaderData } from "react-router";
import { useState } from "react";
import { login } from "../../shopify.server";

import {
  AppProvider,
  Badge,
  BlockStack,
  Box,
  Button,
  Card,
  Divider,
  Grid,
  InlineStack,
  Text,
  TextField,
} from "@shopify/polaris";
import polarisStyles from "@shopify/polaris/build/esm/styles.css?url";
import enTranslations from "@shopify/polaris/locales/en.json";

export const links: LinksFunction = () => [
  { rel: "stylesheet", href: polarisStyles },
];

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const url = new URL(request.url);

  if (url.searchParams.get("shop")) {
    throw redirect(`/app?${url.searchParams.toString()}`);
  }

  return { showForm: Boolean(login) };
};

const features = [
  {
    icon: "✅",
    title: "Allowed & Blocked Zip Codes",
    description:
      "Define exactly which areas you deliver to. Block unsupported zip codes with a clear message so customers know upfront.",
  },
  {
    icon: "🗺️",
    title: "Delivery Zones & ETAs",
    description:
      "Group zip codes into zones and show estimated delivery times. Set custom messages per zip code or zone.",
  },
  {
    icon: "🎨",
    title: "Customisable Widget",
    description:
      "Embed a fully styled zip code checker on your storefront. Control colours, text, position, and more without touching code.",
  },
  {
    icon: "📋",
    title: "Bulk Import & Export",
    description:
      "Upload thousands of zip codes via CSV in seconds. Export your entire list anytime for backup or editing.",
  },
  {
    icon: "🔔",
    title: "Customer Waitlist",
    description:
      "Capture emails from customers in unsupported areas. Notify them when you expand delivery to their zip code.",
  },
  {
    icon: "📦",
    title: "Delivery Rules",
    description:
      "Set zone-based rules including minimum order amounts, delivery fees, cutoff times, and days of the week.",
  },
];

export default function App() {
  const { showForm } = useLoaderData<typeof loader>();
  const [shop, setShop] = useState("");

  return (
    <AppProvider i18n={enTranslations}>
      <div
        style={{
          minHeight: "100vh",
          background: "var(--p-color-bg)",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* ── Header ── */}
        <div
          style={{
            background: "var(--p-color-bg-surface)",
            borderBottom:
              "var(--p-border-width-025) solid var(--p-color-border)",
          }}
        >
          <Box
            paddingInlineStart="400"
            paddingInlineEnd="400"
            paddingBlockStart="300"
            paddingBlockEnd="300"
          >
            <InlineStack gap="200" blockAlign="center">
              <Text as="span" variant="headingMd">
                📍
              </Text>
              <Text as="span" variant="headingMd" fontWeight="bold">
                Zip Code Checker
              </Text>
            </InlineStack>
          </Box>
        </div>

        {/* ── Main ── */}
        <div
          style={{
            flex: 1,
            maxWidth: "1100px",
            width: "100%",
            margin: "0 auto",
            padding: "3rem 2rem 4rem",
            boxSizing: "border-box",
          }}
        >
          {/* Hero */}
          <div
            style={{
              textAlign: "center",
              paddingBottom: "3rem",
            }}
          >
            <BlockStack gap="400" inlineAlign="center">
              {/* Badge */}
              <div>
                <Badge tone="success">SHOPIFY APP</Badge>
              </div>

              {/* Heading */}
              <Text as="h1" variant="heading3xl" fontWeight="bold">
                Control Delivery by{" "}
                <span style={{ color: "var(--p-color-text-success)" }}>
                  Zip Code
                </span>
              </Text>

              {/* Subheading */}
              <div style={{ maxWidth: "600px" }}>
                <Text as="p" variant="bodyLg" tone="subdued" alignment="center">
                  Let customers check delivery availability instantly. Manage
                  allowed and blocked zip codes, set delivery zones, ETAs, and
                  customise your storefront widget — all in one place.
                </Text>
              </div>

              {/* Install form */}
              {showForm && (
                <form
                  method="post"
                  action="/auth/login"
                  style={{ width: "100%", maxWidth: "480px" }}
                >
                  <BlockStack gap="200">
                    <InlineStack gap="200" blockAlign="center" wrap={false}>
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Shopify store domain"
                          labelHidden
                          value={shop}
                          onChange={setShop}
                          name="shop"
                          placeholder="your-store.myshopify.com"
                          autoComplete="off"
                        />
                      </div>
                      <Button variant="primary" submit size="large">
                        Install App
                      </Button>
                    </InlineStack>
                    <Text
                      as="p"
                      variant="bodySm"
                      tone="subdued"
                      alignment="center"
                    >
                      Enter your Shopify store domain to get started
                    </Text>
                  </BlockStack>
                </form>
              )}
            </BlockStack>
          </div>

          {/* Features grid */}
          <Grid>
            {features.map((feature) => (
              <Grid.Cell
                key={feature.title}
                columnSpan={{ xs: 6, sm: 6, md: 4, lg: 4, xl: 4 }}
              >
                <Card>
                  <BlockStack gap="300">
                    <Text as="p" variant="headingXl">
                      {feature.icon}
                    </Text>
                    <Text as="h3" variant="headingSm" fontWeight="bold">
                      {feature.title}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      {feature.description}
                    </Text>
                  </BlockStack>
                </Card>
              </Grid.Cell>
            ))}
          </Grid>
        </div>

        {/* ── Footer ── */}
        <Divider />
        <Box
          background="bg-surface"
          paddingBlockStart="400"
          paddingBlockEnd="400"
          paddingInlineStart="400"
          paddingInlineEnd="400"
        >
          <Text as="p" variant="bodySm" tone="subdued" alignment="center">
            Built for Shopify merchants — Zip Code Checker
          </Text>
        </Box>
      </div>
    </AppProvider>
  );
}
```
